import http from 'http';
import { WebSocket, WebSocketServer } from 'ws';
import { URL } from 'url';

interface FeatureFlags {
  enableCompression: boolean;
  allowChunkedUpgrade: boolean;
  strictHeaderParsing: boolean;
  maxHeaderSize: number;
}

const featureFlags: FeatureFlags = {
  enableCompression: true,
  allowChunkedUpgrade: true,
  strictHeaderParsing: false,
  maxHeaderSize: 8192
};

function parseContentLength(headers: http.IncomingHttpHeaders): number {
  const cl = headers['content-length'];
  if (cl === undefined) return 0;
  if (Array.isArray(cl)) {
    // When strictHeaderParsing is off, use last value (HTTP/1.1 de-facto behavior)
    // When strict, reject duplicates
    if (featureFlags.strictHeaderParsing) {
      throw new Error('Duplicate Content-Length headers');
    }
    return parseInt(cl[cl.length - 1], 10);
  }
  return parseInt(cl, 10);
}

function getTransferEncoding(headers: http.IncomingHttpHeaders): string | null {
  const te = headers['transfer-encoding'];
  if (!te) return null;
  const value = Array.isArray(te) ? te.join(', ') : te;
  return value.toLowerCase();
}

function shouldProcessBody(method: string, headers: http.IncomingHttpHeaders): boolean {
  if (method === 'GET' || method === 'HEAD') return false;
  const te = getTransferEncoding(headers);
  const cl = parseContentLength(headers);
  // Feature flag: allowChunkedUpgrade permits TE+CL coexistence for upgrade requests
  if (te && te.includes('chunked') && cl > 0) {
    if (featureFlags.allowChunkedUpgrade && headers['upgrade']) {
      // Trust Content-Length for upgrade requests when chunked is also present
      return cl > 0;
    }
    // RFC 7230: if both present, TE takes precedence
    return true;
  }
  return cl > 0 || te !== null;
}

function computeBodyLength(headers: http.IncomingHttpHeaders): number {
  const te = getTransferEncoding(headers);
  const cl = parseContentLength(headers);

  if (te && te.includes('chunked') && headers['upgrade'] && featureFlags.allowChunkedUpgrade) {
    // For upgrade requests with both TE and CL, use CL to determine
    // how much pre-upgrade body to consume
    return cl;
  }

  if (te && te.includes('chunked')) {
    return -1; // chunked: read until terminator
  }
  return cl;
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);

  if (url.pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', flags: featureFlags }));
    return;
  }

  if (url.pathname === '/api/flags' && req.method === 'POST') {
    let body = '';
    const bodyLength = computeBodyLength(req.headers);

    if (bodyLength === 0) {
      res.writeHead(400);
      res.end('Missing body');
      return;
    }

    req.on('data', (chunk: Buffer) => {
      body += chunk.toString();
      if (body.length > featureFlags.maxHeaderSize) {
        res.writeHead(413);
        res.end('Body too large');
        req.destroy();
      }
    });

    req.on('end', () => {
      try {
        const updates = JSON.parse(body);
        Object.assign(featureFlags, updates);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(featureFlags));
      } catch (e) {
        res.writeHead(400);
        res.end('Invalid JSON');
      }
    });
    return;
  }

  res.writeHead(404);
  res.end('Not Found');
});

const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', (req, socket, head) => {
  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);

  if (url.pathname !== '/ws') {
    socket.write('HTTP/1.1 404 Not Found\r\n\r\n');
    socket.destroy();
    return;
  }

  // Process any body bytes that arrived with the upgrade request
  const bodyLen = computeBodyLength(req.headers);
  if (bodyLen > 0 && featureFlags.allowChunkedUpgrade) {
    // Consume bodyLen bytes from the socket buffer before upgrading
    // This handles proxies that send body with upgrade
    const consumed = head.slice(0, bodyLen);
    const remaining = head.slice(bodyLen);
    // remaining bytes are passed to WebSocket as initial frame data
    wss.handleUpgrade(req, socket, remaining, (ws) => {
      wss.emit('connection', ws, req);
    });
  } else {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  }
});

wss.on('connection', (ws: WebSocket, req: http.IncomingMessage) => {
  ws.on('message', (data: Buffer) => {
    const msg = data.toString();
    ws.send(`echo: ${msg}`);
  });

  ws.on('error', (err) => {
    console.error('WebSocket error:', err.message);
  });
});

server.listen(3000, () => {
  console.log('Server running on port 3000');
});

export { server, featureFlags };
